 function updateStatus(){if(host){const el=host.querySelector('[data-perf-status]');if(el)el.textContent=status;const time=host.querySelector('[data-perf-time]');if(time)time.textContent=(audio?.currentTime||0).toFixed(1)+' / '+(row?.duration||0).toFixed(1)+' s';}}
