 async function builtin(id){const info=generateBacking(id);return load({id:'BACKING_'+id,kind:'backing',name:TRACKS.find(t=>t.id===id).names[lang],blob:new env.Blob([info.bytes],{type:'audio/wav'}),duration:info.duration,bpm:info.bpm,source:'original-synthesis',completed:true});}
 async function importFile(file){if(!file||!file.size||file.size>50*1024*1024||!(/\.(?:wav|mp3|m4a|aac|ogg|webm|flac)$/i.test(file.name)||file.type.startsWith('audio/')))throw Error(text('badFile'));return load({id:env.crypto.randomUUID(),kind:'backing',name:file.name.slice(0,200),blob:file,source:'user-file',completed:true});}
